from itertools import product, permutations
pdim, udim, vdim = 2, 3, 2
stagedims = [pdim+udim,udim+vdim,vdim]
basis = [(q,r,j) for q in range(2) for r in range(3) for j in range(stagedims[r])]
ix = {b:i for i,b in enumerate(basis)}
N=len(basis)
dh=matrix(QQ,N,N); dv=matrix(QQ,N,N); h=matrix(QQ,N,N)
for q in range(2):
    for j in range(udim):
        dh[ix[q,1,j],ix[q,0,pdim+j]]=1
        h[ix[q,0,pdim+j],ix[q,1,j]]=1
    for j in range(vdim):
        dh[ix[q,2,j],ix[q,1,udim+j]]=1
        h[ix[q,1,udim+j],ix[q,2,j]]=1
ap=matrix(QQ,[[1,2],[0,1]])
du=matrix(QQ,[[1,0,2],[0,1,1],[1,1,0]])
dc=matrix(QQ,[[2,1],[1,0]])
a=matrix(QQ,[[1,-1,2],[0,3,1]])
b=matrix(QQ,[[1,2],[3,0],[-1,2]])
v0=block_matrix([[ap,a],[zero_matrix(QQ,udim,pdim),du]])
v1=block_matrix([[du,b],[zero_matrix(QQ,vdim,udim),dc]])
for r,V in enumerate([v0,v1,dc]):
    for i in range(V.nrows()):
        for j in range(V.ncols()):
            dv[ix[1,r,i],ix[0,r,j]]=(-1)^r*V[i,j]
inc=matrix(QQ,N,2*pdim); proj=matrix(QQ,2*pdim,N)
for q in range(2):
    for j in range(pdim):
        inc[ix[q,0,j],q*pdim+j]=1
        proj[q*pdim+j,ix[q,0,j]]=1
dp=matrix(QQ,2*pdim,2*pdim)
dp[pdim:2*pdim,0:pdim]=ap
Id=identity_matrix(QQ,N); D=dh+dv
inv=Id-dv*h+(dv*h)^2
hp=h*inv; pp=proj*inv
f0=matrix(QQ,[[1,-1,0],[1,0,-1],[0,1,-1]])
f1=matrix(QQ,[[1,-1,1]])
degs=[-1,0,0,0,1]
dmap={0:(1,1),3:(4,1)}
hmap={1:(0,1),4:(3,1)}
def tensor_test(m):
    bs=list(product(range(5),repeat=m)); ids={b:i for i,b in enumerate(bs)}
    n=len(bs); dd=matrix(QQ,n,n,sparse=True); hh=matrix(QQ,n,n,sparse=True)
    ff=matrix(QQ,n,n,sparse=True); sym=matrix(QQ,n,n,sparse=True)
    for col,tup in enumerate(bs):
        if all(j==2 for j in tup): ff[col,col]=1
        for r,j in enumerate(tup):
            sign=(-1)^sum(degs[k] for k in tup[:r])
            if j in dmap:
                out=list(tup);out[r]=dmap[j][0];dd[ids[tuple(out)],col]+=sign
            if j in hmap and all(k==2 for k in tup[:r]):
                out=list(tup);out[r]=hmap[j][0];hh[ids[tuple(out)],col]+=sign
        for perm in permutations(range(m)):
            inversions=sum(degs[tup[perm[i]]]*degs[tup[perm[j]]] for i in range(m) for j in range(i+1,m) if perm[i]>perm[j])
            out=tuple(tup[k] for k in perm)
            sym[ids[out],col]+=QQ((-1)^inversions)/factorial(m)
    hs=sym*hh*sym
    return (dd*hh+hh*dd==identity_matrix(QQ,n)-ff,
            dd*hs+hs*dd==sym-ff*sym,
            dd*sym==sym*dd, sym^2==sym,
            sym.rank()-2*(dd*sym).rank()==1)
tensor_results={m:tensor_test(m) for m in [1,2,3]}
